#include <iostream>
#include <cstring>
#include <queue>
using namespace std;

struct Node{int r,c,dis;};

const int dx[4]={-1,0,1,0},dy[4]={0,-1,0,1};
queue<Node> q;
char buf[15];
int nodeCount,n1,m,lim,totalFlow,pred[202],height[202],gap[203],adjCap[202][202],flow[202][202],path[202];
bool visited[12][12],baseGrid[12][12],foundPath;

void dfsSearch(int u,int bottleneck){
  if(u==nodeCount+1){
    pred[0]=bottleneck;foundPath=true;return;
  }
  int minH=nodeCount+2;
  for(int v=0;v<=nodeCount+1;++v){
    if(flow[u][v]<adjCap[u][v]){
      minH=min(minH,height[v]);
      if(height[u]==height[v]+1){
        path[++totalFlow]=v;
        dfsSearch(v,min(bottleneck,adjCap[u][v]-flow[u][v]));
        if(!visited[0][0]||foundPath)return;
        path[totalFlow--]=0;
      }
    }
    if(flow[v][u]>0){
      minH=min(minH,height[v]);
      if(height[u]==height[v]+1){
        path[++totalFlow]=-v;
        dfsSearch(v,min(bottleneck,flow[v][u]));
        if(!visited[0][0]||foundPath)return;
        path[totalFlow--]=0;
      }
    }
  }
  if(minH+1!=height[u]){
    --gap[height[u]];
    if(gap[height[u]]==0)visited[0][0]=false;
    height[u]=minH+1;
    ++gap[height[u]];
  }
}

bool canAugment(){
  foundPath=false;pred[0]=n1;totalFlow=0;path[0]=0;
  dfsSearch(0,n1);return foundPath;
}

void augment(){
  for(int i=1;i<=totalFlow;++i){
    if(path[i]>0)flow[abs(path[i-1])][path[i]]+=pred[0];
    else flow[-path[i]][abs(path[i-1])]-=pred[0];
  }
}

int main(){
  cin>>m>>lim;
  for(int i=1;i<=m;++i){
    cin>>buf+1;
    for(int j=1;j<=m;++j){
      if(buf[j]=='Z'){
        Node start={i,j,0};q.push(start);
      }else if(buf[j]!='Y'){
        visited[i][j]=true;baseGrid[i][j]=true;
        d0[i][j]=lim;
        int val=buf[j]-'0';
        if(val>0){
          a[i][j]=++nodeCount;
          adjCap[0][nodeCount]=val;
          n1+=val;
        }
      }
    }
  }
  memcpy(baseGrid,visited,sizeof(visited));
  for(int i=1;i<=m;++i){
    cin>>buf+1;
    for(int j=1;j<=m;++j){
      if(buf[j]=='Z'||buf[j]=='Y')continue;
      int val=buf[j]-'0';
      if(val>0){
        b[i][j]=++nodeCount;
        adjCap[nodeCount][m*m+1]=val;
      }
    }
  }
  if(nodeCount!=m*m){
    for(int i=1;i<=m;++i)
      for(int j=1;j<=m;++j)
        if(b[i][j]>0){
          int idx=b[i][j];
          adjCap[idx][nodeCount+1]=adjCap[idx][m*m+1];
          adjCap[idx][m*m+1]=0;
        }
  }
  while(!q.empty()){
    Node cur=q.front();q.pop();
    int r=cur.r,c=cur.c;d0[r][c]=cur.dis;
    for(int k=0;k<4;++k)
      if(visited[r+dx[k]][c+dy[k]]){
        Node next={r+dx[k],c+dy[k],cur.dis+1};q.push(next);
        visited[r+dx[k]][c+dy[k]]=false;
      }
  }
  for(int i=1;i<=m;++i)
    for(int j=1;j<=m;++j){
      if(a[i][j]==0)continue;
      memcpy(visited,baseGrid,sizeof(baseGrid));
      visited[i][j]=false;
      Node start={i,j,0};q.push(start);
      while(!q.empty()){
        Node cur=q.front();q.pop();
        int r=cur.r,c=cur.c;
        if(b[r][c]>0&&cur.dis<=d0[r][c])adjCap[a[i][j]][b[r][c]]=n1;
        if(cur.dis+1>lim||cur.dis>=d0[r][c])continue;
        for(int k=0;k<4;++k)
          if(visited[r+dx[k]][c+dy[k]]){
            Node next={r+dx[k],c+dy[k],cur.dis+1};q.push(next);
            visited[r+dx[k]][c+dy[k]]=false;
          }
      }
    }
  gap[0]=nodeCount+2;visited[0][0]=true;
  while(visited[0][0]&&height[0]<=nodeCount+2)
    while(canAugment())augment();
  int result=0;
  for(int i=1;i<=nodeCount;++i)result+=flow[i][nodeCount+1];
  cout<<result<<endl;return 0;
}
